<?php require_once 'includes/bootstrap.php';$pageTitle='Create account | Samay';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim($_POST['username']??'');$password=$_POST['password']??'';if(!preg_match('/^[A-Za-z0-9_.-]{3,40}$/',$username))$error='Use 3–40 letters, numbers, dots, dashes, or underscores for your username.';elseif(strlen($password)<8)$error='Choose a password with at least 8 characters.';else{try{$hash=password_hash($password,PASSWORD_DEFAULT);$st=$conn->prepare('INSERT INTO users(username,password) VALUES(?,?)');$st->bind_param('ss',$username,$hash);$st->execute();session_regenerate_id(true);$_SESSION['user']=$username;header('Location: account.php');exit;}catch(mysqli_sql_exception $e){$error=$e->getCode()===1062?'That username is already taken. Choose another.':'Could not create the account. Make sure database.sql has been imported.';}}}require 'includes/header.php'; ?>
<section class="auth-shell"><div class="auth-art"><div class="kicker">Make it yours</div><h2>Time is personal.</h2><p>Save your favourites and keep your collection close.</p></div><form class="auth-form" method="post"><div class="kicker">Join Samay</div><h1>Create account.</h1><p>Your next favourite is just around the corner.</p><?php if($error): ?><div class="form-error"><?=h($error)?></div><?php endif; ?><?php csrf_field(); ?><div class="form-field"><label for="username">Choose a username</label><input id="username" name="username" autocomplete="username" minlength="3" maxlength="40" required></div><div class="form-field"><label for="password">Create a password</label><input id="password" type="password" name="password" autocomplete="new-password" minlength="8" required><small>At least 8 characters.</small></div><button class="button form-submit" type="submit">Create my account ↗</button><div class="form-note">Already a member? <a href="login.php"><u>Sign in</u></a></div></form></section><?php require 'includes/footer.php'; ?>
